\centering
\small
\resizebox{\columnwidth}{!}{%
\begin{tabular}{lrrrrrrr}
\toprule
& \multicolumn{4}{c}{\textbf{Regression (BCS $\to$ Accuracy)}} & \multicolumn{2}{c}{\textbf{Quartile $\Delta$}} \\
